public class Solution {
  /**
   * 差分数组：+d 落在 start，-d 落在 min(end, n-1)+1，最后一遍前缀和还原。
   * diff 长度 n+1；累加全程 long（两个 ±2e9 相加就超出 int 上限 2.147e9）。
   */
  public static long[] applyRanges(int n, int[] starts, int[] ends, int[] deltas) {
    if (n < 0) throw new IllegalArgumentException("n must be >= 0");
    long[] diff = new long[n + 1];
    for (int k = 0; k < starts.length; k++) {
      int a = starts[k];
      int b = ends[k];
      if (a < 0 || b < a) throw new IllegalArgumentException("bad range");
      if (a >= n) continue;               // 整条落在未分配的 key 上，跳过
      int last = Math.min(b, n - 1);      // end 越界按截断处理，绝不产生 n+1 下标
      long d = deltas[k];
      diff[a] += d;
      diff[last + 1] -= d;
    }
    long[] out = new long[n];
    long run = 0;
    for (int j = 0; j < n; j++) {
      run += diff[j];
      out[j] = run;
    }
    return out;
  }
}

