public class Solution {
  // 朴素：逐条区间直接覆盖写。复杂度 O(n*m)，并且权重在 int 域累加 ——
  // 溢出后静默返回负数（先 int 相加、再赋给 long，溢出早已发生）。
  public static long[] applyRanges(int n, int[] starts, int[] ends, int[] deltas) {
    int[] weight = new int[n];
    for (int k = 0; k < starts.length; k++) {
      int a = starts[k];
      int b = ends[k];
      if (a < 0 || b < a) throw new IllegalArgumentException("bad range");
      for (int j = a; j <= b && j < n; j++) {
        weight[j] += deltas[k];
      }
    }
    long[] out = new long[n];
    for (int j = 0; j < n; j++) out[j] = weight[j];
    return out;
  }
}
